import os
import sqlite3
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/app/data/users.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        email TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        department TEXT,
        active INTEGER DEFAULT 1
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        target_user TEXT,
        performed_by TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by department and role for org chart display.
    Supports partial matching on department names."""
    department = request.args.get('department', '')
    role = request.args.get('role', '')
    include_inactive = request.args.get('include_inactive', '0')

    # Build query with filters
    base_query = "SELECT id, username, email, role, department FROM users WHERE 1=1"

    if department:
        # Allow partial department name matching for UX
        base_query += f" AND department LIKE '%{department}%'"

    if role:
        base_query += f" AND role = '{role}'"

    if include_inactive != '1':
        base_query += " AND active = 1"

    try:
        db = get_db()
        cursor = db.execute(base_query)
        results = [dict(row) for row in cursor.fetchall()]
        return jsonify({'users': results, 'count': len(results)})
    except Exception as e:
        app.logger.error(f"Search error: {e}")
        return jsonify({'error': 'Search failed'}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user details by ID."""
    db = get_db()
    cursor = db.execute(
        "SELECT id, username, email, role, department FROM users WHERE id = ?",
        (user_id,)
    )
    user = cursor.fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'User not found'}), 404

@app.route('/api/users', methods=['POST'])
def create_user():
    """Create a new user (admin only - enforced by upstream auth)."""
    data = request.get_json()
    required = ['username', 'email', 'department']
    if not all(k in data for k in required):
        return jsonify({'error': 'Missing required fields'}), 400

    try:
        db = get_db()
        db.execute(
            "INSERT INTO users (username, email, role, department) VALUES (?, ?, ?, ?)",
            (data['username'], data['email'], data.get('role', 'user'), data['department'])
        )
        db.commit()
        # Audit log
        db.execute(
            "INSERT INTO audit_log (action, target_user, performed_by) VALUES (?, ?, ?)",
            ('create_user', data['username'], request.headers.get('X-Authenticated-User', 'unknown'))
        )
        db.commit()
        return jsonify({'status': 'created'}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'Username already exists'}), 409
    except Exception as e:
        app.logger.error(f"Create user error: {e}")
        return jsonify({'error': 'Creation failed'}), 500

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'healthy'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=os.environ.get('FLASK_DEBUG', '0') == '1')
